+		edge_set.insert(edge_hash_key(vi0, vi3));
+		edge_set.insert(edge_hash_key(vi1, vi2));
+		edge_set.insert(edge_hash_key(vi1, vi3));
+		edge_set.insert(edge_hash_key(vi2, vi3));
